sys_script_include.script:
var testeObj = Class.create();
testeObj.prototype = {
    initialize: function() {},

    transformarEmObj: function(obj) {

        // Transformar o objeto em um array
        var array = Object.values(obj.DadosDaLucAtual);
        var array2 = [];

        // Iterar sobre cada elemento do array
        array.forEach(function(dadosLuc) {
            var luc_atual_v2 = dadosLuc.luc_atual_v2;
            var area_anterior_m = dadosLuc.area_anterior_m;

            var obj = {
                lucAtual: luc_atual_v2,
                areaAnterior_m: area_anterior_m
            };

            // Adicionar o objeto ao novo array
            array2.push(obj);
        });

        // Log para depuração
        gs.info("ARRAY2: " + JSON.stringify(array2));

		return array2;

    },

    type: 'testeObj'
};
